/* ===================== BÀI 19 · Fixed-point và IEEE 754 floating point ===================== */
/* Bài 19 · Fixed-point và IEEE 754 floating point (CM02.05) — sinh bởi tools/author/maytinh/m19.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l19"),{id:"l19",scenarios:[{"label": "Ví dụ: Mã hóa 5,75 sang float32", "note": "Đổi sang hệ 2, chuẩn hóa, cộng độ lệch 127.", "steps": [{"t": "5,75 sang nhị phân: 101,11₂", "html": "<p class=\"mt-calc\">5 = 101₂ · 0,75 = 0,5 + 0,25 = 0,11₂ → 5,75 = <b>101,11₂<\/b><\/p>", "say": "<p>Phần sau dấu phẩy nhị phân có trọng số 1/2, 1/4, 1/8…<\/p>"}, {"t": "Chuẩn hóa: 1,0111₂ × 2²", "html": "<p class=\"mt-calc\">Dời dấu phẩy sang trái 2 vị trí: 101,11 = 1,0111 × 2²<\/p>", "ask": {"q": "Số mũ thật là 2. Trường số mũ float32 (độ lệch 127) lưu giá trị nào?", "o": ["2", "129", "127"], "a": 1}}, {"t": "Dấu 0 · số mũ 129 · phần định trị 0111…", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dấu (1)<\/th><th scope=\"col\">Số mũ (8)<\/th><th scope=\"col\">Phần định trị (23)<\/th><th scope=\"col\">Hex<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td class=\"new\">10000001<\/td><td>011100000000…<\/td><td>0x40B80000<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">Số mũ lưu = 2 + 127 = 129 = 1000 0001 · bit “1,” đầu tiên không lưu (bit ẩn)<\/p>"}, {"t": "Kết quả: 0x40B80000", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dấu (1)<\/th><th scope=\"col\">Số mũ (8)<\/th><th scope=\"col\">Phần định trị (23)<\/th><th scope=\"col\">Hex<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>10000001<\/td><td>011100000000…<\/td><td class=\"new\">0x40B80000<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">0 10000001 01110000000000000000000 = <b>0x40B80000<\/b><\/p>", "say": "<p>Kiểm tra bằng cách giải mã ngược: (−1)⁰ × 1,0111₂ × 2^(129 − 127) = 1,4375 × 4 = 5,75 ✓.<\/p>"}]}, {"label": "Ví dụ: Giải mã 0xC0200000", "note": "Tách dấu, số mũ, phần định trị rồi tính ngược.", "steps": [{"t": "Giải mã 0xC0200000", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dấu (1)<\/th><th scope=\"col\">Số mũ (8)<\/th><th scope=\"col\">Phần định trị (23)<\/th><th scope=\"col\">Hex<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>10000000<\/td><td>010000000000…<\/td><td>0xC0200000<\/td><\/tr><\/tbody><\/table>", "say": "<p>Tách 32 bit thành ba trường.<\/p>"}, {"t": "Dấu 1 → số âm; số mũ 128 → 2¹", "html": "<p class=\"mt-calc\">1000 0000 = 128 → mũ thật 128 − 127 = 1<\/p>"}, {"t": "Phần định trị 1,01₂ = 1,25 → −2,5", "html": "<p class=\"mt-calc\">(−1)¹ × 1,25 × 2¹ = <b>−2,5<\/b><\/p>", "ask": {"q": "Dấu 1, số mũ thật 1, phần định trị 1,25. Giá trị là bao nhiêu?", "o": ["2,5", "−2,5", "−1,25"], "a": 1}}]}, {"label": "Ví dụ: Dấu phẩy tĩnh ×100 và Q8.8", "note": "Số nguyên kèm vị trí dấu phẩy quy ước.", "steps": [{"t": "Số thực bằng số nguyên: nhân với hằng số", "html": "<p class=\"mt-calc\">Nhiệt độ 23,75 °C lưu dạng ×100: số nguyên <b>2375<\/b><\/p>", "say": "<p>Dấu phẩy tĩnh: lưu số nguyên, quy ước vị trí dấu phẩy cố định. Rất phổ biến ở cảm biến, PLC, vi điều khiển không có bộ tính số thực.<\/p>"}, {"t": "Dạng nhị phân Q8.8: nhân với 256", "html": "<p class=\"mt-calc\">23,75 × 256 = <b>6 080 = 0x17C0<\/b> · byte cao 0x17 = 23 là phần nguyên, byte thấp 0xC0 = 192/256 = 0,75<\/p>", "ask": {"q": "Q8.8 lưu giá trị 0x0380. Giá trị thực là bao nhiêu?", "o": ["3,5", "896", "3,8"], "a": 0}}, {"t": "Độ phân giải và miền cố định", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dạng<\/th><th scope=\"col\">Bước nhỏ nhất<\/th><th scope=\"col\">Miền (16 bit không dấu)<\/th><\/tr><\/thead><tbody><tr><td>×100<\/td><td>0,01<\/td><td>0 … 655,35<\/td><\/tr><tr><td>Q8.8<\/td><td>1/256 ≈ 0,0039<\/td><td>0 … 255,996<\/td><\/tr><\/tbody><\/table>", "say": "<p>Dấu phẩy tĩnh: phép tính nhanh, kết quả lặp lại chính xác, nhưng miền và độ phân giải cố định. Dấu phẩy động: miền rất rộng, nhưng sai số làm tròn thay đổi theo độ lớn.<\/p>"}]}, {"label": "Bẫy: 0,1 không lưu chính xác", "note": "Giá trị thật được lưu của 0,1 trong float32 và double.", "steps": [{"t": "0,1 trong hệ 2 là số vô hạn tuần hoàn", "html": "<p class=\"mt-calc\">0,1 = 0,0001100110011…₂ (nhóm 0011 lặp mãi)<\/p>", "say": "<p>Giống 1/3 = 0,333… trong hệ 10: 1/10 không viết hữu hạn được trong hệ 2.<\/p>"}, {"t": "float32 làm tròn: 0x3DCCCCCD", "html": "<p class=\"mt-calc\">Giá trị thật được lưu: <b>0,100000001490116119384765625<\/b><\/p>", "ask": {"q": "Biến float x = 0,1. Giá trị lưu trong máy có đúng bằng 0,1 không?", "o": ["Đúng bằng 0,1", "Gần 0,1 nhưng không bằng"], "a": 1}}, {"t": "double chính xác hơn nhưng vẫn không đúng", "html": "<p class=\"mt-calc\">double 0,1 = 0,1000000000000000055511151231257827…<\/p>", "say": "<p>Mọi số thực dấu phẩy động là số hữu tỉ có mẫu là lũy thừa của 2. Số như 0,1 luôn bị làm tròn.<\/p>"}]}, {"label": "Bẫy: 0,1 + 0,2 ≠ 0,3", "note": "Không so sánh bằng hai số thực đã tính toán.", "steps": [{"t": "0,1 + 0,2 bằng 0,3?", "html": "<p class=\"mt-calc\">Kiểu double (64 bit), làm tròn về số gần nhất<\/p>", "say": "<p>Ba số đều đã bị làm tròn khi lưu.<\/p>"}, {"t": "Kết quả: 0,30000000000000004", "html": "<p class=\"mt-calc\">0,1 + 0,2 = <b>0,30000000000000004<\/b> · 0,3 được lưu là 0,299999999999999988…<\/p>", "ask": {"q": "Trong double, biểu thức 0,1 + 0,2 == 0,3 cho kết quả gì?", "o": ["Đúng (true)", "Sai (false)"], "a": 1}}, {"t": "Sửa: so sánh với sai số cho phép", "html": "<p class=\"mt-calc\">|a − b| ≤ ε, với ε chọn theo bài toán (ví dụ 10⁻⁹ cho giá trị cỡ 1)<\/p>", "say": "<p>Không so sánh bằng (==) hai số thực đã qua tính toán. Với tiền tệ, dùng số nguyên theo đơn vị nhỏ nhất (đồng, xu) hoặc kiểu thập phân.<\/p>"}]}, {"label": "Lỗi: Bộ đếm float32 ngừng tăng ở 16 777 216", "note": "float32 chỉ có 24 bit có nghĩa.", "steps": [{"t": "float32 có 24 bit độ chính xác", "html": "<p class=\"mt-calc\">23 bit lưu + 1 bit ẩn = 24 bit → số nguyên tới 2²⁴ = 16 777 216 lưu chính xác<\/p>", "say": "<p>Khoảng 24 × log₁₀2 ≈ 7,2 chữ số thập phân có nghĩa.<\/p>"}, {"t": "16 777 217 lưu vào float32 → 16 777 216", "html": "<p class=\"mt-calc\">2²⁴ + 1 cần 25 bit có nghĩa → làm tròn về số chẵn gần nhất: <b>16 777 216<\/b><\/p>", "ask": {"q": "Lưu 16 777 217 vào float32 rồi đọc ra được gì?", "o": ["16 777 217", "16 777 216", "Báo lỗi tràn số"], "a": 1}}, {"t": "Hậu quả: bộ đếm dùng float32 ngừng tăng", "html": "<p class=\"mt-calc\">x = 16 777 216; x = x + 1 → vẫn 16 777 216<\/p>", "say": "<p>Không dùng float32 cho bộ đếm, mã sản phẩm, thời gian tích lũy lâu. Dùng số nguyên, hoặc double (53 bit, khoảng 15–16 chữ số có nghĩa).<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l19"),"l19",[{"kind": "num", "t": "Giải mã float32", "d": "<p>Ghi giá trị thập phân của mẫu bit float32.<\/p>", "items": [{"q": "0x3F800000", "a": 1.0}, {"q": "0x40400000", "a": 3.0}, {"q": "0xBF800000", "a": -1.0}, {"q": "0x41200000", "a": 10.0}], "hints": ["Tách: bit 31 là dấu, bit 30–23 là số mũ, còn lại là phần định trị.", "0x3F800000: số mũ 0111 1111 = 127 → mũ thật 0, phần định trị 0 → 1,0.", "0x41200000: số mũ 130 → 2³; phần định trị 01… → 1,25."], "why": "1,0; 0x40400000: mũ 128 → 2¹ × 1,5 = 3; 0xBF800000: −1; 0x41200000: 2³ × 1,25 = 10."}, {"kind": "num", "t": "Các trường của IEEE 754", "d": "<p>Trả lời bằng số hệ 10.<\/p>", "items": [{"q": "Số bit phần định trị được lưu của float32", "a": 23}, {"q": "Độ lệch số mũ của double", "a": 1023}, {"q": "Trường số mũ float32 của 5,75", "a": 129}, {"q": "Trường số mũ float32 của 0,5", "a": 126}], "hints": ["float32: 1 + 8 + 23 bit; double: 1 + 11 + 52 bit.", "Trường số mũ = mũ thật + 127.", "0,5 = 1,0 × 2⁻¹."], "why": "23 bit; độ lệch double 1023; 5,75 = 1,0111 × 2² → 129; 0,5 = 1,0 × 2⁻¹ → 126."}, {"kind": "num", "t": "Dấu phẩy tĩnh", "d": "<p>Làm tròn 4 chữ số thập phân khi cần.<\/p>", "items": [{"q": "23,75 °C lưu dạng ×100: số nguyên?", "a": 2375}, {"q": "1,5 lưu dạng Q8.8: số nguyên?", "a": 384}, {"q": "Q8.8 giá trị lưu 0x0380: giá trị thực?", "a": 3.5, "tol": 0.0001}, {"q": "Bước nhỏ nhất (độ phân giải) của Q8.8?", "a": 0.00390625, "tol": 0.0001}], "hints": ["Dạng ×100: nhân 100.", "Q8.8: nhân 256 (hoặc chia 256 khi đọc).", "0x0380 = 896."], "why": "2 375; 1,5 × 256 = 384; 896 ÷ 256 = 3,5; 1/256 ≈ 0,0039."}]);

makeQuiz("quiz19","score19",[{"q": "Trong float32, trường số mũ lưu 130. Số mũ thật là bao nhiêu?", "o": ["130", "3", "−3", "2"], "a": 1, "e": "130 − 127 = 3. Độ lệch 127 cho phép lưu cả mũ âm bằng số không dấu."}, {"q": "Vì sao 0,1 không được lưu chính xác trong float32 hay double?", "o": ["Vì 0,1 quá nhỏ", "Vì máy tính dùng hệ 10", "Vì 1/10 là số nhị phân tuần hoàn vô hạn", "Vì thiếu bit dấu"], "a": 2, "e": "Giống 1/3 trong hệ 10; mọi số dấu phẩy động có mẫu là lũy thừa của 2."}, {"q": "Cách so sánh hai số double a, b đã qua tính toán an toàn hơn là gì?", "o": ["a == b", "Kiểm tra |a − b| ≤ ε với ε phù hợp", "Đổi cả hai sang chuỗi rồi so", "Nhân cả hai với 10"], "a": 1, "e": "Sai số làm tròn làm a == b sai cả khi về toán học chúng bằng nhau."}, {"q": "Lưu 16 777 217 vào float32 rồi đọc lại được gì?", "o": ["16 777 216", "16 777 217", "Vô cực", "0"], "a": 0, "e": "float32 có 24 bit có nghĩa; 2²⁴ + 1 cần 25 bit nên bị làm tròn."}, {"q": "Cảm biến gửi nhiệt độ dạng số nguyên ×10, giá trị 253. Nhiệt độ là bao nhiêu?", "o": ["253 °C", "2,53 °C", "0,253 °C", "25,3 °C"], "a": 3, "e": "Chia cho hệ số 10: 25,3 °C. Luôn đọc hệ số tỉ lệ trong tài liệu thiết bị."}]);

